# ---- Chapter on Ohm's and Kirchhoff's laws: pulls the voltage divider out of chapter 1 and adds three more ----
_RULES = [
 dict(ex="Ohm's law (volts, amps and ohms)", title="The one equation to remember", level=1,
  idea="Voltage pushes, resistance holds back, current is how much gets through. Ohm's law ties them together: volts = amps × ohms.",
  tries=["Read the current through R1 (9 V battery, 1 kΩ). Check it with 9 ÷ 1000.",
         "Change R1 to 3 kΩ. Predict the current, then run it.",
         "Keep R1 at 1 kΩ but make the battery 3 V. What current now? What do you notice compared with question 2?"],
  answers=["9 mA (0.009 A).",
           "3 mA: three times the resistance, a third of the current.",
           "3 mA again. Cutting the push to a third has exactly the same effect as tripling the brake."],
  why="Cover the letter you want in the triangle V / (I × R): V = I × R, I = V ÷ R, R = V ÷ I. Every circuit in this book is this one rule used many times."),
 dict(ex="Voltage divider (two resistors share the battery)", title="Sharing the voltage", level=1,
  idea="Two resistors in a row split the battery's voltage. The bigger resistor takes the bigger share.",
  tries=["Predict the voltage at A (the middle) with R1 = 1 kΩ and R2 = 2 kΩ on 9 V. Then run it.",
         "Make R2 = 1 kΩ. What happens to A?",
         "Make both resistors 100 kΩ. Does A change? Does the current?"],
  answers=["6 V. R2 is two-thirds of the total, so it takes two-thirds of 9 V.",
           "A drops to 4.5 V: equal resistors split the voltage equally.",
           "A stays 4.5 V (only the ratio matters), but the current drops 100 times. Dividers made from big resistors waste almost no power."],
  why="The same current flows through both resistors. The voltage across each is current × its resistance, so the shares match the resistances. Formula: the middle voltage = battery × R2 ÷ (R1 + R2)."),
 dict(ex="Kirchhoff's loop (the voltages add up to the battery)", title="Round the loop and back", level=2,
  idea="Kirchhoff's voltage law: walk once round any loop of a circuit and the voltage rises and falls add up to zero. The battery's rise is shared out as falls across the resistors.",
  tries=["Read A, B and C. How much voltage does each resistor 'use up'? (Subtract neighbours.)",
         "Add the three drops. Do they equal the battery?",
         "The current is the same through all three. Use Ohm's law on R3 to check it. What is it?"],
  answers=["R1 drops 2 V, R2 drops 4 V, R3 drops 6 V.",
           "2 + 4 + 6 = 12 V. Yes, exactly the battery.",
           "6 V ÷ 3 kΩ = 2 mA. (And 12 V ÷ the total 6 kΩ = 2 mA too.)"],
  why="Voltage is like height: climb a hill (battery) and you must come down the same total height (resistors) to get back to where you started. Series resistors add up: R total = R1 + R2 + R3."),
 dict(ex="Current divider (parallel resistors share the flow)", title="Where does the current go?", level=2,
  idea="Kirchhoff's current law: at any junction, the current going in equals the current going out. Nothing is lost or made. When a wire forks, the flow splits, with more going down the easier path.",
  tries=["Switch the current dots on and watch them at the top junction. Which branch carries more?",
         "Read the three currents. Do the two branch currents add up to the battery's?",
         "Make R2 = 1 kΩ as well. How does the flow split now? What does the battery supply?"],
  answers=["R1 (1 kΩ), the smaller resistor.",
           "9 mA + 4.5 mA = 13.5 mA. Yes.",
           "An equal 9 mA each, 18 mA in total. Two equal roads share the traffic equally, and the battery works harder because the total resistance fell to 500 Ω."],
  why="Each branch has the full battery voltage across it, so each current is V ÷ its own R. Parallel branches ADD their currents, which is why plugging in more appliances makes a plug socket carry more current. Parallel resistors: 1/R total = 1/R1 + 1/R2."),
]
for _i, _c in enumerate(CHAPTERS):
    _c[3][:] = [it for it in _c[3] if not it["ex"].startswith("Voltage divider")]
